function validate([distance, start, destination]) {
  if (!Array.isArray(distance) || distance.length < 1 || distance.length > 10000) return 'distance needs 1 to 10^4 values.';
  if (!distance.every(d => Number.isInteger(d) && d >= 0 && d <= 10000)) return 'Each distance is a whole number from 0 to 10^4.';
  if (!Number.isInteger(start) || start < 0 || start >= distance.length) return 'start must be a stop index.';
  if (!Number.isInteger(destination) || destination < 0 || destination >= distance.length) return 'destination must be a stop index.';
  return null;
}

