function distanceBetweenBusStops(distance, start, destination) {
  const n = distance.length;
  // Ride forward from start until reaching destination.
  let forward = 0;
  for (let stop = start; stop !== destination; stop = (stop + 1) % n) forward += distance[stop];
  // Ride backward from start until reaching destination.
  let backward = 0;
  for (let stop = start; stop !== destination; stop = (stop - 1 + n) % n) backward += distance[(stop - 1 + n) % n];
  return forward < backward ? forward : backward;
}

